-- Close anon-key exposure: enable RLS (default-deny) on all public tables that had it off.
-- App uses custom auth + server-side service_role (bypasses RLS), so server routes are unaffected.
ALTER TABLE public.enterprise_users              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_sessions           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_memberships        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_audit_events       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_workspaces         ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_workspace_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_workspace_domains  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_workspace_modules  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_workspace_tasks    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_module_definitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_agent_runs         ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_connector_events   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_metric_records     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_source_records     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_source_change_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_knowledge_chunks   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_knowledge_embeddings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_leads              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_lead_activities    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.enterprise_lead_hunt_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.production_ledger             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wcm_incidents                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.iot_telemetry                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assets                        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.supermega_campaign_clicks     ENABLE ROW LEVEL SECURITY;

begin;

-- Isolated rehearsal only. This packet quarantines the exact legacy public
-- catalog observed on 2026-08-04. It does not touch app_private, customer rows,
-- service_role authority, or the protected production target by itself.
do $guard$
declare
  expected_tables constant text[] := array[
    'assets',
    'enterprise_agent_runs',
    'enterprise_audit_events',
    'enterprise_connector_events',
    'enterprise_knowledge_chunks',
    'enterprise_knowledge_embeddings',
    'enterprise_lead_activities',
    'enterprise_lead_hunt_profiles',
    'enterprise_leads',
    'enterprise_memberships',
    'enterprise_metric_records',
    'enterprise_module_definitions',
    'enterprise_sessions',
    'enterprise_source_change_events',
    'enterprise_source_records',
    'enterprise_users',
    'enterprise_workspace_domains',
    'enterprise_workspace_modules',
    'enterprise_workspace_profiles',
    'enterprise_workspace_tasks',
    'enterprise_workspaces',
    'iot_telemetry',
    'production_ledger',
    'supermega_campaign_clicks',
    'supermega_leads',
    'supermega_sales_runs',
    'wcm_incidents'
  ]::text[];
  expected_sequences constant text[] := array[
    'supermega_leads_id_seq',
    'supermega_sales_runs_id_seq'
  ]::text[];
  observed_tables text[];
  observed_sequences text[];
begin
  if current_user <> 'postgres' then
    raise exception using
      errcode = '42501',
      message = 'public browser quarantine requires the reviewed postgres migration role';
  end if;

  if to_regrole('anon') is null
    or to_regrole('authenticated') is null
    or to_regrole('service_role') is null
    or to_regrole('supabase_admin') is null
  then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine requires the Supabase API and administration roles';
  end if;

  select coalesce(array_agg(relation.relname order by relation.relname), array[]::text[])
  into observed_tables
  from pg_class relation
  join pg_namespace schema_record on schema_record.oid = relation.relnamespace
  where schema_record.nspname = 'public'
    and relation.relkind in ('r', 'p');

  select coalesce(array_agg(relation.relname order by relation.relname), array[]::text[])
  into observed_sequences
  from pg_class relation
  join pg_namespace schema_record on schema_record.oid = relation.relnamespace
  where schema_record.nspname = 'public'
    and relation.relkind = 'S';

  if observed_tables <> expected_tables then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine table inventory changed; regenerate the reviewed packet';
  end if;
  if observed_sequences <> expected_sequences then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine sequence inventory changed; regenerate the reviewed packet';
  end if;

  if exists (
    select 1
    from pg_proc function_record
    join pg_namespace schema_record on schema_record.oid = function_record.pronamespace
    where schema_record.nspname = 'public'
      and (
        has_function_privilege('anon', function_record.oid, 'EXECUTE')
        or has_function_privilege('authenticated', function_record.oid, 'EXECUTE')
      )
  ) then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine found a browser-callable routine; review it explicitly';
  end if;

  if exists (
    select 1
    from unnest(expected_tables) as expected_table(name)
    cross join unnest(array['SELECT', 'INSERT', 'UPDATE', 'DELETE'])
      as required_privilege(name)
    where not has_table_privilege(
      'service_role',
      format('%I.%I', 'public', expected_table.name),
      required_privilege.name
    )
  ) or exists (
    select 1
    from unnest(expected_sequences) as expected_sequence(name)
    cross join unnest(array['USAGE', 'SELECT']) as required_privilege(name)
    where not has_sequence_privilege(
      'service_role',
      format('%I.%I', 'public', expected_sequence.name),
      required_privilege.name
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine server dependency baseline changed';
  end if;
end
$guard$;

alter default privileges for role postgres in schema public
  revoke all privileges on tables from public, anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all privileges on sequences from public, anon, authenticated;
alter default privileges for role postgres in schema public
  revoke execute on functions from public, anon, authenticated;

-- supabase_admin owns a second set of default-privilege rules. Altering them
-- requires membership in that role, which the `postgres` migration role does NOT
-- have on managed Supabase: an unconditional attempt fails with 42501 and aborts
-- the whole packet. Proven on preview branch fpnxjptpzaztkhzeemzj, 2026-08-08.
-- Attempt it only when the running role can, and report honestly when it cannot.
do $supabase_admin_defaults$
begin
  if pg_has_role(current_user, 'supabase_admin', 'member') then
    alter default privileges for role supabase_admin in schema public
      revoke all privileges on tables from public, anon, authenticated;
    alter default privileges for role supabase_admin in schema public
      revoke all privileges on sequences from public, anon, authenticated;
    alter default privileges for role supabase_admin in schema public
      revoke execute on functions from public, anon, authenticated;
  else
    raise notice 'public browser quarantine: supabase_admin default privileges left unchanged (current role is not a member). Objects created BY supabase_admin will still auto-grant to browser roles; ask Supabase support to revoke these.';
  end if;
end
$supabase_admin_defaults$;

revoke all privileges on table public.assets from public, anon, authenticated;
revoke all privileges on table public.enterprise_agent_runs from public, anon, authenticated;
revoke all privileges on table public.enterprise_audit_events from public, anon, authenticated;
revoke all privileges on table public.enterprise_connector_events from public, anon, authenticated;
revoke all privileges on table public.enterprise_knowledge_chunks from public, anon, authenticated;
revoke all privileges on table public.enterprise_knowledge_embeddings from public, anon, authenticated;
revoke all privileges on table public.enterprise_lead_activities from public, anon, authenticated;
revoke all privileges on table public.enterprise_lead_hunt_profiles from public, anon, authenticated;
revoke all privileges on table public.enterprise_leads from public, anon, authenticated;
revoke all privileges on table public.enterprise_memberships from public, anon, authenticated;
revoke all privileges on table public.enterprise_metric_records from public, anon, authenticated;
revoke all privileges on table public.enterprise_module_definitions from public, anon, authenticated;
revoke all privileges on table public.enterprise_sessions from public, anon, authenticated;
revoke all privileges on table public.enterprise_source_change_events from public, anon, authenticated;
revoke all privileges on table public.enterprise_source_records from public, anon, authenticated;
revoke all privileges on table public.enterprise_users from public, anon, authenticated;
revoke all privileges on table public.enterprise_workspace_domains from public, anon, authenticated;
revoke all privileges on table public.enterprise_workspace_modules from public, anon, authenticated;
revoke all privileges on table public.enterprise_workspace_profiles from public, anon, authenticated;
revoke all privileges on table public.enterprise_workspace_tasks from public, anon, authenticated;
revoke all privileges on table public.enterprise_workspaces from public, anon, authenticated;
revoke all privileges on table public.iot_telemetry from public, anon, authenticated;
revoke all privileges on table public.production_ledger from public, anon, authenticated;
revoke all privileges on table public.supermega_campaign_clicks from public, anon, authenticated;
revoke all privileges on table public.supermega_leads from public, anon, authenticated;
revoke all privileges on table public.supermega_sales_runs from public, anon, authenticated;
revoke all privileges on table public.wcm_incidents from public, anon, authenticated;

revoke all privileges on sequence public.supermega_leads_id_seq
from public, anon, authenticated;
revoke all privileges on sequence public.supermega_sales_runs_id_seq
from public, anon, authenticated;

do $verify$
begin
  if exists (
    select 1
    from pg_class relation
    join pg_namespace schema_record on schema_record.oid = relation.relnamespace
    cross join (values ('anon'), ('authenticated')) as browser_role(name)
    cross join unnest(array[
      'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
    ]) as forbidden_privilege(name)
    where schema_record.nspname = 'public'
      and relation.relkind in ('r', 'p')
      and has_table_privilege(
        browser_role.name,
        relation.oid,
        forbidden_privilege.name
      )
  ) or exists (
    select 1
    from pg_class relation
    join pg_namespace schema_record on schema_record.oid = relation.relnamespace
    cross join (values ('anon'), ('authenticated')) as browser_role(name)
    cross join unnest(array['USAGE', 'SELECT', 'UPDATE']) as forbidden_privilege(name)
    where schema_record.nspname = 'public'
      and relation.relkind = 'S'
      and has_sequence_privilege(browser_role.name, relation.oid, forbidden_privilege.name)
  ) then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine left a browser object grant';
  end if;

  -- Split by owner: a postgres-owned leak is ours to fix and must fail the packet.
  -- A supabase_admin-owned leak cannot be revoked without membership in that role,
  -- so failing on it would make the packet permanently unappliable. Application
  -- objects are created by postgres, so the residual is reported, not fatal.
  if exists (
    select 1
    from pg_default_acl default_acl
    join pg_roles owner_role on owner_role.oid = default_acl.defaclrole
    join pg_namespace schema_record on schema_record.oid = default_acl.defaclnamespace
    cross join lateral aclexplode(default_acl.defaclacl) privilege_record
    left join pg_roles grantee_role on grantee_role.oid = privilege_record.grantee
    where owner_role.rolname = 'postgres'
      and schema_record.nspname = 'public'
      and default_acl.defaclobjtype in ('r', 'S', 'f')
      and (
        privilege_record.grantee = 0
        or grantee_role.rolname in ('anon', 'authenticated')
      )
  ) then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine left an automatic browser grant';
  end if;

  if exists (
    select 1
    from pg_default_acl default_acl
    join pg_roles owner_role on owner_role.oid = default_acl.defaclrole
    join pg_namespace schema_record on schema_record.oid = default_acl.defaclnamespace
    cross join lateral aclexplode(default_acl.defaclacl) privilege_record
    left join pg_roles grantee_role on grantee_role.oid = privilege_record.grantee
    where owner_role.rolname = 'supabase_admin'
      and schema_record.nspname = 'public'
      and default_acl.defaclobjtype in ('r', 'S', 'f')
      and (
        privilege_record.grantee = 0
        or grantee_role.rolname in ('anon', 'authenticated')
      )
  ) then
    raise notice 'public browser quarantine: supabase_admin default privileges still grant browser roles. Not reachable from the postgres migration role; raise with Supabase support.';
  end if;

  if exists (
    select 1
    from unnest(array['SELECT', 'INSERT', 'UPDATE', 'DELETE'])
      as required_privilege(name)
    where not has_table_privilege(
      'service_role',
      'public.supermega_leads',
      required_privilege.name
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'public browser quarantine changed the retained server contact path';
  end if;
end
$verify$;

commit;

-- Factory payroll has no direct browser table grants. A narrow RPC enforces live
-- membership, valid sessions, workflow transitions and an append-only audit log.
create schema if not exists factory_payroll;
revoke all on schema factory_payroll from public, anon, authenticated;
create table if not exists factory_payroll.members (
  user_id uuid primary key references auth.users(id),
  role text not null check(role in ('payroll','manager','admin')),
  active boolean not null default true,
  updated_at timestamptz not null default now()
);
create table if not exists factory_payroll.runs (
  id uuid primary key default gen_random_uuid(),
  period text not null check(length(period) between 1 and 100),
  source text not null check(length(source) between 1 and 200),
  employees jsonb not null check(jsonb_typeof(employees)='array'),
  total numeric(20,2) not null,
  employee_count integer not null,
  fingerprint text not null,
  status text not null default 'draft' check(status in ('draft','submitted','approved','returned')),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  version integer not null default 1,
  decision_by uuid references auth.users(id),
  decision_note text,
  unique(period,fingerprint)
);
create table if not exists factory_payroll.events (
  id bigint generated always as identity primary key,
  run_id uuid references factory_payroll.runs(id),
  actor uuid not null references auth.users(id),
  action text not null,
  detail jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create index if not exists fp_runs_created on factory_payroll.runs(created_at desc);
create index if not exists fp_runs_page on factory_payroll.runs(created_at desc,id desc);
create index if not exists fp_runs_preparer on factory_payroll.runs(created_by);
create index if not exists fp_runs_decider on factory_payroll.runs(decision_by);
create index if not exists fp_events_run on factory_payroll.events(run_id,id);
create index if not exists fp_events_actor_time on factory_payroll.events(actor,created_at);
alter table factory_payroll.members enable row level security;
alter table factory_payroll.runs enable row level security;
alter table factory_payroll.events enable row level security;
revoke all on all tables in schema factory_payroll from public,anon,authenticated;

create or replace function factory_payroll.run_action(principal_id uuid, action text, payload jsonb default '{}', actor_name text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := principal_id; member_role text; result jsonb; run factory_payroll.runs;
  entry jsonb; entries jsonb; count_rows integer; sum_pay numeric := 0; amount numeric;
  period_value text; source_value text; target uuid; target_role text; active_value boolean;
begin
  if uid is null then raise exception 'Sign in required' using errcode='42501'; end if;
  select role into member_role from factory_payroll.members where user_id=uid and active;
  if member_role is null then raise exception 'Payroll access has not been assigned.' using errcode='42501'; end if;
  if jsonb_typeof(payload)<>'object' or octet_length(payload::text)>5000000 then raise exception 'Invalid request'; end if;
  if action='me' then return jsonb_build_object('userId',uid,'role',member_role); end if;
  if action='list' then
    select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from (
      select id,period,source,total,employee_count,status,created_at,created_by,version,decision_note
      from factory_payroll.runs
      where payload#>>'{cursor,id}' is null or (created_at,id)<((payload#>>'{cursor,created_at}')::timestamptz,(payload#>>'{cursor,id}')::uuid)
      order by created_at desc,id desc limit 100
    ) x; return result;
  end if;
  if action='get' then
    select * into run from factory_payroll.runs where id=(payload->>'id')::uuid;
    if not found then raise exception 'Payroll run not found'; end if;
    select coalesce(jsonb_agg(to_jsonb(e) order by e.id),'[]') into result from factory_payroll.events e where run_id=run.id;
    return to_jsonb(run)||jsonb_build_object('events',result);
  end if;
  if action='usage' then
    return jsonb_build_object('runs',(select count(*) from factory_payroll.runs),'pending',(select count(*) from factory_payroll.runs where status='submitted'),'approved',(select count(*) from factory_payroll.runs where status='approved'),'activeMembers',(select count(*) from factory_payroll.members where active),'lastActivity',(select max(created_at) from factory_payroll.events));
  end if;
  if action='members' then
    if member_role<>'admin' then raise exception 'Admin access required' using errcode='42501'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('userId',m.user_id,'email',u.email,'role',m.role,'active',m.active) order by u.email),'[]') into result from factory_payroll.members m join auth.users u on u.id=m.user_id;
    return result;
  end if;
  if action='backup' then
    if member_role<>'admin' then raise exception 'Admin access required' using errcode='42501'; end if;
    return jsonb_build_object('format','ytf-payroll-backup-v1','exportedAt',now(),'runs',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from factory_payroll.runs r),'events',(select coalesce(jsonb_agg(to_jsonb(e)),'[]') from factory_payroll.events e),'members',(select coalesce(jsonb_agg(to_jsonb(m)),'[]') from factory_payroll.members m));
  end if;
  if (select count(*) from factory_payroll.events where actor=uid and created_at>now()-interval '1 minute')>=30 then raise exception 'Too many changes. Try again shortly.'; end if;
  if action='set_member' then
    if member_role<>'admin' then raise exception 'Admin access required' using errcode='42501'; end if;
    select id into target from auth.users where lower(email)=lower(trim(payload->>'email')) and email_confirmed_at is not null and coalesce(is_anonymous,false)=false;
    if target is null then raise exception 'That person must create and verify their sign-in account first.'; end if;
    target_role:=payload->>'role';active_value:=coalesce((payload->>'active')::boolean,true);
    if target_role not in ('payroll','manager','admin') then raise exception 'Invalid role'; end if;
    if target=uid and (target_role<>'admin' or not active_value) then raise exception 'You cannot remove your own admin access.'; end if;
    insert into factory_payroll.members(user_id,role,active) values(target,target_role,active_value) on conflict(user_id) do update set role=excluded.role,active=excluded.active,updated_at=now();
    insert into factory_payroll.events(actor,action,detail) values(uid,action,jsonb_build_object('userId',target,'role',target_role,'active',active_value,'displayName',actor_name));
    return jsonb_build_object('ok',true);
  end if;
  if action='create' then
    if member_role not in ('payroll','admin') then raise exception 'Payroll staff access required' using errcode='42501'; end if;
    entries:=payload->'employees';period_value:=trim(payload->>'period');source_value:=trim(payload->>'source');
    if jsonb_typeof(entries)<>'array' or jsonb_array_length(entries) not between 1 and 20000 then raise exception 'Use 1–20,000 employee rows'; end if;
    if period_value is null or source_value is null then raise exception 'Period and source required'; end if;
    count_rows:=jsonb_array_length(entries);
    for entry in select value from jsonb_array_elements(entries) loop
      if jsonb_typeof(entry)<>'object' or length(trim(entry->>'employeeId')) not between 1 and 100 or length(trim(entry->>'name')) not between 1 and 160 or entry->>'employeeId' is null or entry->>'name' is null then raise exception 'Each employee needs an ID and name'; end if;
      if coalesce(entry->>'netPay','') !~ '^-?[0-9]{1,14}(\.[0-9]{1,2})?$' then raise exception 'Invalid net pay. Use amounts with at most two decimals.'; end if;
      amount:=(entry->>'netPay')::numeric;
      if amount<0 then raise exception 'Negative net pay must be corrected before sharing.'; end if;
      sum_pay:=sum_pay+amount;
      if sum_pay>1000000000000 then raise exception 'Run total exceeds the supported limit of 1 trillion. Split the payroll batch.'; end if;
    end loop;
    if (select count(distinct lower(trim(value->>'employeeId'))) from jsonb_array_elements(entries))<>count_rows then raise exception 'Duplicate employee IDs must be corrected'; end if;
    insert into factory_payroll.runs(period,source,employees,total,employee_count,fingerprint,created_by)
      values(period_value,source_value,entries,sum_pay,count_rows,encode(extensions.digest(entries::text,'sha256'),'hex'),uid) returning * into run;
    insert into factory_payroll.events(run_id,actor,action,detail) values(run.id,uid,'created',jsonb_build_object('displayName',actor_name));
    return to_jsonb(run);
  end if;
  select * into run from factory_payroll.runs where id=(payload->>'id')::uuid for update;
  if not found then raise exception 'Payroll run not found'; end if;
  if (payload->>'version')::integer is distinct from run.version then raise exception 'This run changed. Refresh before continuing.' using errcode='40001'; end if;
  if action='submit' then
    if member_role not in ('payroll','admin') or run.created_by<>uid or run.status<>'draft' then raise exception 'Only the preparer can submit a draft' using errcode='42501'; end if;
    update factory_payroll.runs set status='submitted',version=version+1,updated_at=now() where id=run.id returning * into run;
  elsif action in ('approve','return') then
    if member_role not in ('manager','admin') or run.created_by=uid or run.status<>'submitted' then raise exception 'A different approving manager must review a submitted run' using errcode='42501'; end if;
    if length(trim(coalesce(payload->>'note',''))) not between 3 and 1000 then raise exception 'Enter a review note (3–1000 characters)'; end if;
    update factory_payroll.runs set status=case when action='approve' then 'approved' else 'returned' end,decision_by=uid,decision_note=trim(payload->>'note'),version=version+1,updated_at=now() where id=run.id returning * into run;
  else raise exception 'Unsupported action'; end if;
  insert into factory_payroll.events(run_id,actor,action,detail) values(run.id,uid,action,jsonb_build_object('version',run.version,'note',run.decision_note,'displayName',actor_name));
  return to_jsonb(run);
end;
$$;
revoke all on function factory_payroll.run_action(uuid,text,jsonb,text) from public,anon,authenticated;
create or replace function public.fp_action(action text,payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();sid uuid:=nullif(auth.jwt()->>'session_id','')::uuid;
begin
 if uid is null or sid is null or not exists(select 1 from auth.sessions s where s.id=sid and s.user_id=uid and (s.not_after is null or s.not_after>now())) then raise exception 'Session expired. Sign in again.' using errcode='42501';end if;
 return factory_payroll.run_action(uid,action,payload,null);
end $$;
revoke all on function public.fp_action(text,jsonb) from public,anon;
grant execute on function public.fp_action(text,jsonb) to authenticated;
comment on function public.fp_action(text,jsonb) is 'Factory payroll API: explicit membership and live-session checks; no self-approval; salary changes create new runs.';

-- Separate PIN authentication for explicitly assigned shared payroll roles.
-- Starting credentials are provisioned separately; never store plaintext in source.
create table if not exists factory_payroll.role_pins(
 role text primary key check(role in ('payroll','manager','admin')),
 user_id uuid unique not null references auth.users(id),
 pin_hash text not null,
 failures integer not null default 0,
 locked_until timestamptz,
 updated_at timestamptz not null default now()
);
create table if not exists factory_payroll.pin_sessions(
 token_hash text primary key,
 user_id uuid not null references auth.users(id),
 display_name text not null,
 expires_at timestamptz not null,
 created_at timestamptz not null default now()
);
create index if not exists fp_pin_sessions_user on factory_payroll.pin_sessions(user_id);
alter table factory_payroll.role_pins enable row level security;
alter table factory_payroll.pin_sessions enable row level security;
revoke all on factory_payroll.role_pins,factory_payroll.pin_sessions from public,anon,authenticated;

create or replace function public.fp_pin_login(role_name text,pin text,display_name text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare account factory_payroll.role_pins; session_token text; n integer;
begin
 select * into account from factory_payroll.role_pins where role=role_name for update;
 if not found then return jsonb_build_object('error','Incorrect role or PIN.');end if;
 if account.locked_until>now() then return jsonb_build_object('error','Too many attempts. Try again in 15 minutes.');end if;
 if coalesce(pin,'') !~ '^[0-9]{5,8}$' or extensions.crypt(pin,account.pin_hash)<>account.pin_hash then
   n:=case when account.locked_until is not null and account.locked_until<=now() then 1 else account.failures+1 end;
   update factory_payroll.role_pins set failures=n,locked_until=case when n>=10 then now()+interval '15 minutes' else null end where role=role_name;
   return jsonb_build_object('error','Incorrect role or PIN.');
 end if;
 if length(trim(coalesce(display_name,''))) not between 2 and 60 then return jsonb_build_object('error','Enter your name (2–60 characters).');end if;
 if not exists(select 1 from factory_payroll.members where user_id=account.user_id and active) then return jsonb_build_object('error','This account is disabled.');end if;
 update factory_payroll.role_pins set failures=0,locked_until=null where role=role_name;
 delete from factory_payroll.pin_sessions where expires_at<=now();
 session_token:=encode(extensions.gen_random_bytes(32),'hex');
 insert into factory_payroll.pin_sessions(token_hash,user_id,display_name,expires_at) values(encode(extensions.digest(session_token,'sha256'),'hex'),account.user_id,trim(display_name),now()+interval '12 hours');
 return jsonb_build_object('token',session_token,'userId',account.user_id,'role',role_name,'displayName',trim(display_name));
end $$;

create or replace function public.fp_pin_action(session_token text,action text,payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path='' as $$
declare session factory_payroll.pin_sessions; member_role text; target factory_payroll.role_pins; current_account factory_payroll.role_pins; result jsonb;new_pin text;n integer;
begin
 if coalesce(session_token,'') !~ '^[a-f0-9]{64}$' then raise exception 'Sign in required' using errcode='42501';end if;
 select * into session from factory_payroll.pin_sessions where token_hash=encode(extensions.digest(session_token,'sha256'),'hex') and expires_at>now();
 if not found then raise exception 'Session expired. Sign in again.' using errcode='42501';end if;
 select role into member_role from factory_payroll.members where user_id=session.user_id and active;
 if member_role is null then raise exception 'Access revoked' using errcode='42501';end if;
 if action='logout' then delete from factory_payroll.pin_sessions where token_hash=session.token_hash;return jsonb_build_object('ok',true);end if;
 if action='set_pin' then
   select * into current_account from factory_payroll.role_pins where user_id=session.user_id for update;
   if not found then raise exception 'Role account not found';end if;
   if current_account.locked_until>now() then return jsonb_build_object('error','Too many attempts. Try again in 15 minutes.');end if;
   if extensions.crypt(coalesce(payload->>'currentPin',''),current_account.pin_hash)<>current_account.pin_hash then
     n:=case when current_account.locked_until<=now() then 1 else current_account.failures+1 end;
     update factory_payroll.role_pins set failures=n,locked_until=case when n>=10 then now()+interval '15 minutes' else null end where role=current_account.role;
     return jsonb_build_object('error','Current PIN is incorrect');
   end if;
   if member_role<>'admin' and payload->>'role'<>member_role then raise exception 'Admin access required' using errcode='42501';end if;
   new_pin:=payload->>'pin';
   if coalesce(new_pin,'') !~ '^[0-9]{5,8}$' or new_pin is distinct from payload->>'confirmPin' then raise exception 'Enter matching 5–8 digit PINs';end if;
   select * into target from factory_payroll.role_pins where role=payload->>'role' for update;
   if not found then raise exception 'Unknown role';end if;
   if exists(select 1 from factory_payroll.role_pins p where p.role<>target.role and extensions.crypt(new_pin,p.pin_hash)=p.pin_hash) then raise exception 'Use a different PIN for each role';end if;
   update factory_payroll.role_pins set pin_hash=extensions.crypt(new_pin,extensions.gen_salt('bf',10)),failures=0,locked_until=null,updated_at=now() where role=target.role;
   delete from factory_payroll.pin_sessions where user_id=target.user_id;
   insert into factory_payroll.events(actor,action,detail) values(session.user_id,'pin_changed',jsonb_build_object('role',target.role,'displayName',session.display_name));
   return jsonb_build_object('ok',true,'signedOut',target.user_id=session.user_id);
 end if;
 result:=factory_payroll.run_action(session.user_id,action,payload,session.display_name);
 return result;
end $$;
revoke all on function public.fp_pin_login(text,text,text),public.fp_pin_action(text,text,jsonb) from public;
grant execute on function public.fp_pin_login(text,text,text),public.fp_pin_action(text,text,jsonb) to anon,authenticated;

begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
-- Source: 20260817090000_private_trial_backend_v12_billing_rail.sql
-- Billing rail v1 (hq/strategy/BILLING-RAIL-DESIGN.md sections 3, 4.4, 6;
-- Gate 9 successor). Three tenant-side tables record founder billing actions:
--
--   billing_invoices      one row per founder-issued invoice packet, sealed by
--                         its sha256 digest, revision version-guarded, status
--                         issued -> paid | void (draft never reaches the server;
--                         drafts live in the founder's local CLI packets).
--   billing_events        the evidence spine: one append-only event per
--                         transition, immutable and server-timestamped exactly
--                         like app_private.workspace_events.
--   billing_entitlements  one projection row per workspace. Legal transitions
--                         none -> granted -> revoked -> granted, each a guarded
--                         revision increment; premiumUnlocked derives from
--                         status = 'granted' and nowhere else.
--
-- RLS posture (design 4.4): deny by default, NO policies. No policy or table
-- privilege grants the runtime member role (supermega_trial_backend) anything:
-- operators must never see or write invoices. Writes happen only through the
-- founder-run privileged provisioner connection
-- (supermega_runtime/billing_rail.py), the managed_activation.py pattern.
-- Nothing in this migration sends an invoice, requests money, confirms a
-- payment, or grants access by itself.
--
-- DEVIATION: design 4.3 has the tenant runtime deriving premiumUnlocked from
-- billing_entitlements.status live. This slice's rails require ZERO policies
-- and ZERO grants for the runtime member role on every billing table, so the
-- runtime's premiumUnlocked probe (PostgresTrialStore._premium_unlocked)
-- observes the missing SELECT privilege and fail-closes to false. The
-- derivation code ships and is tested; lighting it up is one later migration
-- adding a workspace-GUC-scoped SELECT policy on billing_entitlements ONLY --
-- a separate founder decision, exactly how v6 shipped the self-serve INSERT
-- path dark and v11 lit it up.

do $guard$
begin
  if not exists (
    select 1
    from app_private.trial_schema_meta
    where component = 'private_trial_backend'
      and schema_version = 11
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 requires schema version 11';
  end if;
end
$guard$;

create table app_private.billing_invoices (
  workspace_id text not null,
  invoice_id text not null check (invoice_id ~ '^INV-[A-Za-z0-9-]{4,40}$'),
  status text not null check (status in ('issued', 'paid', 'void')),
  invoice_digest text not null check (invoice_digest ~ '^[0-9a-f]{64}$'),
  payload_json jsonb not null check (jsonb_typeof(payload_json) = 'object'),
  revision bigint not null check (revision >= 1),
  created_at timestamptz not null default transaction_timestamp(),
  updated_at timestamptz not null default transaction_timestamp(),
  primary key (workspace_id, invoice_id),
  check (workspace_id = btrim(workspace_id) and workspace_id <> '')
);

create function app_private.guard_billing_invoice()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, app_private
as $function$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'issued' then
      raise exception using errcode = '55000', message = 'billing invoices are recorded at issued status';
    end if;
    if new.revision <> 1 then
      raise exception using errcode = '55000', message = 'initial billing invoice revision must be one';
    end if;
    new.created_at := transaction_timestamp();
    new.updated_at := transaction_timestamp();
    return new;
  end if;
  if tg_op = 'DELETE' then
    raise exception using errcode = '55000', message = 'billing invoices cannot be deleted';
  end if;
  if new.workspace_id is distinct from old.workspace_id
     or new.invoice_id is distinct from old.invoice_id
     or new.invoice_digest is distinct from old.invoice_digest
     or new.payload_json is distinct from old.payload_json
     or new.created_at is distinct from old.created_at then
    raise exception using errcode = '55000', message = 'billing invoice identity is immutable';
  end if;
  if old.status <> 'issued' or new.status not in ('paid', 'void') then
    raise exception using errcode = '55000', message = 'billing invoice status can only transition from issued to paid or void';
  end if;
  if new.revision <> old.revision + 1 then
    raise exception using errcode = '40001', message = 'billing invoice revision must increment by one';
  end if;
  new.updated_at := transaction_timestamp();
  return new;
end
$function$;

create trigger billing_invoice_guard
before insert or update or delete on app_private.billing_invoices
for each row execute function app_private.guard_billing_invoice();

create table app_private.billing_events (
  event_id uuid primary key,
  workspace_id text not null,
  command_id uuid not null,
  command_fingerprint text not null check (command_fingerprint ~ '^[0-9a-f]{64}$'),
  event_type text not null check (event_type in (
    'billing.invoice.issued',
    'billing.payment.confirmed',
    'billing.invoice.voided',
    'billing.entitlement.granted',
    'billing.entitlement.revoked',
    'billing.refund.recorded'
  )),
  actor_id text not null,
  actor_kind text not null check (actor_kind = 'human'),
  payload_json jsonb not null check (jsonb_typeof(payload_json) = 'object'),
  result_json jsonb not null check (jsonb_typeof(result_json) = 'object'),
  created_at timestamptz not null default transaction_timestamp(),
  unique (workspace_id, command_id),
  check (workspace_id = btrim(workspace_id) and workspace_id <> ''),
  check (actor_id = btrim(actor_id) and actor_id <> '')
);

create index billing_events_timeline_idx
  on app_private.billing_events (workspace_id, created_at desc);

create function app_private.reject_billing_event_mutation()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, app_private
as $function$
begin
  raise exception using
    errcode = '55000',
    message = 'billing events are immutable';
end
$function$;

create trigger billing_events_immutable
before update or delete on app_private.billing_events
for each row execute function app_private.reject_billing_event_mutation();

create function app_private.stamp_billing_event_insert()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, app_private
as $function$
begin
  new.created_at := transaction_timestamp();
  return new;
end
$function$;

create trigger billing_events_server_timestamp
before insert on app_private.billing_events
for each row execute function app_private.stamp_billing_event_insert();

create table app_private.billing_entitlements (
  workspace_id text primary key,
  tier text not null check (tier = 'premium'),
  status text not null check (status in ('none', 'granted', 'revoked')),
  granted_event_id uuid,
  invoice_digest text check (invoice_digest ~ '^[0-9a-f]{64}$'),
  revision bigint not null check (revision >= 1),
  updated_at timestamptz not null default transaction_timestamp(),
  check (workspace_id = btrim(workspace_id) and workspace_id <> ''),
  check (
    (status = 'granted' and granted_event_id is not null and invoice_digest is not null)
    or (status in ('none', 'revoked') and granted_event_id is null and invoice_digest is null)
  )
);

create function app_private.guard_billing_entitlement()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog, app_private
as $function$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'none' or new.revision <> 1 then
      raise exception using errcode = '55000', message = 'billing entitlement rows start at none with revision one';
    end if;
    new.updated_at := transaction_timestamp();
    return new;
  end if;
  if tg_op = 'DELETE' then
    raise exception using errcode = '55000', message = 'billing entitlements cannot be deleted';
  end if;
  if new.workspace_id is distinct from old.workspace_id
     or new.tier is distinct from old.tier then
    raise exception using errcode = '55000', message = 'billing entitlement identity is immutable';
  end if;
  if not (
    (old.status = 'none' and new.status = 'granted')
    or (old.status = 'granted' and new.status = 'revoked')
    or (old.status = 'revoked' and new.status = 'granted')
  ) then
    raise exception using errcode = '55000', message = 'billing entitlement transitions are none to granted, granted to revoked, or revoked to granted';
  end if;
  if new.revision <> old.revision + 1 then
    raise exception using errcode = '40001', message = 'billing entitlement revision must increment by one';
  end if;
  new.updated_at := transaction_timestamp();
  return new;
end
$function$;

create trigger billing_entitlement_guard
before insert or update or delete on app_private.billing_entitlements
for each row execute function app_private.guard_billing_entitlement();

alter table app_private.billing_invoices enable row level security;
alter table app_private.billing_invoices force row level security;
alter table app_private.billing_events enable row level security;
alter table app_private.billing_events force row level security;
alter table app_private.billing_entitlements enable row level security;
alter table app_private.billing_entitlements force row level security;

-- Deny by default, and deliberately no policies: the runtime member role gets
-- nothing (no select, no policy, no capability path). The foundation's default
-- privileges already keep the API roles out; the explicit revokes below keep
-- that boundary visible in this file, the v6 idiom.
revoke all on app_private.billing_invoices
  from public, anon, authenticated, service_role;
revoke all on app_private.billing_events
  from public, anon, authenticated, service_role;
revoke all on app_private.billing_entitlements
  from public, anon, authenticated, service_role;
revoke all on function app_private.guard_billing_invoice()
  from public, anon, authenticated, service_role;
revoke all on function app_private.reject_billing_event_mutation()
  from public, anon, authenticated, service_role;
revoke all on function app_private.stamp_billing_event_insert()
  from public, anon, authenticated, service_role;
revoke all on function app_private.guard_billing_entitlement()
  from public, anon, authenticated, service_role;

update app_private.trial_schema_meta
set schema_version = 12,
    applied_at = transaction_timestamp()
where component = 'private_trial_backend'
  and schema_version = 11;

do $verify$
begin
  if not exists (
    select 1
    from app_private.trial_schema_meta
    where component = 'private_trial_backend'
      and schema_version = 12
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 did not reach schema version 12';
  end if;

  if (
    select count(*)
    from pg_class relation
    join pg_namespace schema_record on schema_record.oid = relation.relnamespace
    where schema_record.nspname = 'app_private'
      and relation.relname in ('billing_invoices', 'billing_events', 'billing_entitlements')
      and relation.relrowsecurity
      and relation.relforcerowsecurity
  ) <> 3 then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 billing tables must force row level security';
  end if;

  if exists (
    select 1
    from pg_policies
    where schemaname = 'app_private'
      and tablename in ('billing_invoices', 'billing_events', 'billing_entitlements')
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 billing tables must carry no policies';
  end if;

  if exists (
    select 1
    from unnest(array['billing_invoices', 'billing_events', 'billing_entitlements']) table_name,
         unnest(array['supermega_trial_backend', 'anon', 'authenticated', 'service_role']) role_name,
         unnest(array['SELECT', 'INSERT', 'UPDATE', 'DELETE']) privilege_name
    where has_table_privilege(role_name, format('app_private.%I', table_name), privilege_name)
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 billing tables must grant the runtime and API roles nothing';
  end if;

  if (
    select count(*)
    from pg_trigger trigger_record
    join pg_class relation on relation.oid = trigger_record.tgrelid
    join pg_namespace schema_record on schema_record.oid = relation.relnamespace
    where schema_record.nspname = 'app_private'
      and not trigger_record.tgisinternal
      and (
        (relation.relname = 'billing_invoices'
          and trigger_record.tgname = 'billing_invoice_guard')
        or (relation.relname = 'billing_events'
          and trigger_record.tgname = 'billing_events_immutable')
        or (relation.relname = 'billing_events'
          and trigger_record.tgname = 'billing_events_server_timestamp')
        or (relation.relname = 'billing_entitlements'
          and trigger_record.tgname = 'billing_entitlement_guard')
      )
  ) <> 4 then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v12 billing hardening triggers are missing';
  end if;
end
$verify$;

-- Source: 20260818090000_private_trial_backend_v13_billing_entitlement_read.sql
-- Billing entitlement read policy (BILLING-RAIL-DESIGN.md 4.3, the DEVIATION
-- noted in the v12 migration header). v12 shipped billing dark on purpose:
-- zero policies, zero grants, so the founder's billing rail could ship and be
-- proven WITHOUT deciding, in the same breath, to expose anything to the
-- runtime. This migration is that separate decision, narrowly scoped: it
-- grants the non-BYPASSRLS runtime role exactly one thing -- SELECT on its
-- OWN workspace's billing_entitlements row -- and nothing else. It does not
-- touch billing_invoices or billing_events; those stay founder-only forever.
-- A session can learn only "is this workspace premium", never see an amount,
-- a payment reference, an invoice, or any other workspace's entitlement.
--
-- This mirrors exactly how v6 shipped the self-serve INSERT path dark and v11
-- lit it up as its own reviewable unit (SELF-SERVE-REMEDIATION-FINDINGS.md).
-- Applying this migration to production is a separate founder decision from
-- applying v12: v12 makes billing possible to operate; v13 makes the paid
-- flag visible to the product surface that reads it
-- (PostgresTrialStore._premium_unlocked, already shipped and dark-tested).
--
-- Reviewed and local-rehearsed only as of authoring; NOT proven on a hosted
-- branch and NOT applied anywhere. Do not apply to production without a
-- disposable-branch proof first, per house discipline.

do $guard$
begin
  if not exists (
    select 1
    from app_private.trial_schema_meta
    where component = 'private_trial_backend'
      and schema_version = 12
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 requires schema version 12';
  end if;
end
$guard$;

-- A session may read only the entitlement row for the workspace its own GUC
-- identity is bound to. No INSERT/UPDATE/DELETE policy is added: the runtime
-- can observe entitlement, never change it. Every write stays exclusively on
-- the founder-run BillingLedger provisioner connection (v12 header).
create policy billing_entitlements_self_read
on app_private.billing_entitlements
for select
to supermega_trial_backend
using (
  workspace_id = (select current_setting('app.workspace_id', true))
);

grant select on app_private.billing_entitlements to supermega_trial_backend;

update app_private.trial_schema_meta
set schema_version = 13,
    applied_at = transaction_timestamp()
where component = 'private_trial_backend'
  and schema_version = 12;

do $verify$
begin
  if not exists (
    select 1
    from app_private.trial_schema_meta
    where component = 'private_trial_backend'
      and schema_version = 13
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 did not reach schema version 13';
  end if;

  if (
    select count(*)
    from pg_policies
    where schemaname = 'app_private'
      and cmd = 'SELECT'
      and permissive = 'PERMISSIVE'
      and array_to_string(roles, ',') = 'supermega_trial_backend'
      and tablename = 'billing_entitlements'
      and policyname = 'billing_entitlements_self_read'
  ) <> 1 then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 billing entitlement read policy is missing';
  end if;

  -- billing_invoices and billing_events must remain completely dark: no
  -- policy of any kind, no privilege of any kind, for the runtime role.
  if exists (
    select 1
    from pg_policies
    where schemaname = 'app_private'
      and tablename in ('billing_invoices', 'billing_events')
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 must not add policies on billing_invoices or billing_events';
  end if;

  if exists (
    select 1
    from unnest(array['billing_invoices', 'billing_events']) table_name,
         unnest(array['SELECT', 'INSERT', 'UPDATE', 'DELETE']) privilege_name
    where has_table_privilege(
      'supermega_trial_backend', format('app_private.%I', table_name), privilege_name
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 must not grant the runtime role any privilege on billing_invoices or billing_events';
  end if;

  if not has_table_privilege(
    'supermega_trial_backend', 'app_private.billing_entitlements', 'SELECT'
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 billing entitlement select grant is missing';
  end if;

  if exists (
    select 1
    from unnest(array['INSERT', 'UPDATE', 'DELETE']) privilege_name
    where has_table_privilege(
      'supermega_trial_backend', 'app_private.billing_entitlements', privilege_name
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'private trial backend v13 must grant the runtime role read-only access to billing_entitlements';
  end if;
end
$verify$;

-- Source: 20260907024457_self_serve_durable_attempt_budget.sql
-- Additive v13 capability, not a tenant-schema version change. Apply separately
-- through the owner-gated migration flow; no signup/activation window is opened.
create table app_private.self_serve_attempt_budgets (
  actor_id uuid primary key,
  attempts timestamptz[] not null default '{}',
  claim_conflicts timestamptz[] not null default '{}',
  constraint self_serve_attempt_budget_bounded check (
    cardinality(attempts) <= 5
    and cardinality(claim_conflicts) <= cardinality(attempts)
    and array_position(attempts, null) is null
    and array_position(claim_conflicts, null) is null
    and claim_conflicts <@ attempts
  )
);
alter table app_private.self_serve_attempt_budgets enable row level security;
alter table app_private.self_serve_attempt_budgets force row level security;
revoke all on app_private.self_serve_attempt_budgets from public, anon, authenticated;
grant select, insert on app_private.self_serve_attempt_budgets to supermega_trial_backend;
grant update (attempts, claim_conflicts) on app_private.self_serve_attempt_budgets
  to supermega_trial_backend;

create policy self_serve_attempt_budget_actor_only
on app_private.self_serve_attempt_budgets for all to supermega_trial_backend
using (
  actor_id = nullif(current_setting('app.actor_id', true), '')::uuid
  and current_setting('app.actor_kind', true) = 'human'
)
with check (
  actor_id = nullif(current_setting('app.actor_id', true), '')::uuid
  and current_setting('app.actor_kind', true) = 'human'
);

-- Explicit invoker rights: no privileged path around forced RLS. Runtime binds
-- the verified actor/session first. No email, IP, claim, business or token stored.
create function app_private.reserve_self_serve_attempt()
returns timestamptz language plpgsql security invoker set search_path = ''
as $$
declare
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
  previous timestamptz[];
  recent timestamptz[];
  stamp timestamptz;
begin
  if actor is null or current_setting('app.actor_kind', true) is distinct from 'human' then
    raise exception 'self_serve_budget_actor_required';
  end if;
  insert into app_private.self_serve_attempt_budgets (actor_id) values (actor)
    on conflict (actor_id) do nothing;
  -- READ COMMITTED + row lock means a waiter sees the prior committed budget.
  select attempts into strict previous from app_private.self_serve_attempt_budgets
    where actor_id = actor for update;
  -- Read the database clock AFTER the lock, not transaction start / client time.
  stamp := clock_timestamp();
  if exists (select 1 from unnest(previous) t where t >= stamp) then
    raise exception 'self_serve_budget_clock_invalid';
  end if;
  select coalesce(array_agg(t order by t), '{}'::timestamptz[]) into recent
    from unnest(previous) t where t > stamp - interval '24 hours';
  if cardinality(recent) >= 5 then
    return null;
  end if;
  update app_private.self_serve_attempt_budgets
    set attempts = array_append(recent, stamp),
        claim_conflicts = array(
          select t from unnest(claim_conflicts) t where t = any(recent) order by t
        )
    where actor_id = actor;
  return stamp;
end;
$$;

-- Conflict marking is idempotent and can only refer to an admitted attempt.
-- A crash after the claim transaction can undercount diagnostics, never refund
-- admission. Conflicts are NOT customer/commercial proof or authorization.
create function app_private.mark_self_serve_claim_conflict(admitted_at timestamptz)
returns boolean language plpgsql security invoker set search_path = ''
as $$
declare
  actor uuid := nullif(current_setting('app.actor_id', true), '')::uuid;
begin
  if actor is null or current_setting('app.actor_kind', true) is distinct from 'human' then
    raise exception 'self_serve_budget_actor_required';
  end if;
  update app_private.self_serve_attempt_budgets
    set claim_conflicts = case when admitted_at = any(claim_conflicts)
      then claim_conflicts else array_append(claim_conflicts, admitted_at) end
    where actor_id = actor and admitted_at = any(attempts);
  return found;
end;
$$;

