    jsonb_typeof(preview) = 'object'
    and preview - array['siteName','pages'] = '{}'::jsonb
    and jsonb_typeof(preview->'siteName') = 'string'
    and jsonb_typeof(preview->'pages') = 'array'
    and jsonb_array_length(preview->'pages') between 1 and 4
